package main

import (
	"errors"
	"fmt"
	"strconv"
)

var ErrDivByZero = errors.New("division by zero")

// divide returns a result and an error: the caller has to look at both.
func divide(a, b int) (int, error) {
	if b == 0 {
		return 0, ErrDivByZero
	}
	return a / b, nil
}

// minMax names its results: they document the return values and start at zero.
func minMax(xs []int) (lo, hi int) {
	if len(xs) == 0 {
		return // naked return: returns lo and hi as they are (0, 0)
	}
	lo, hi = xs[0], xs[0]
	for _, x := range xs[1:] {
		lo, hi = min(lo, x), max(hi, x) // min and max builtins: Go 1.21
	}
	return lo, hi
}

func main() {
	if q, err := divide(7, 2); err == nil {
		fmt.Println("7/2 =", q)
	}
	if _, err := divide(1, 0); errors.Is(err, ErrDivByZero) {
		fmt.Println("error:", err)
	}

	n, err := strconv.Atoi("42") // the same (value, error) shape everywhere
	fmt.Println(n, err)

	fmt.Println(minMax([]int{4, -2, 9, 0}))
	fmt.Println(minMax(nil))
}

files.examples/02_variadic_closures.go:
package main

import (
	"fmt"
	"strings"
)

func sum(nums ...int) int { // nums is an ordinary []int inside
	total := 0
	for _, n := range nums {
		total += n
	}
	return total
}

func double(nums ...int) {
	for i := range nums {
		nums[i] *= 2
	}
}

// counter returns a closure; each closure keeps its own count alive.
func counter() func() int {
	count := 0
	return func() int {
		count++
		return count
	}
}

func apply(items []string, f func(string) string) []string {
	out := make([]string, 0, len(items))
	for _, it := range items {
		out = append(out, f(it))
	}
	return out
}

func main() {
	fmt.Println(sum(), sum(1, 2, 3))

	xs := []int{1, 2, 3}
	fmt.Println(sum(xs...)) // spread a slice into a variadic call
	double(xs...)           // no copy: double writes into xs's backing array
	fmt.Println(xs)

	next, other := counter(), counter()
	fmt.Println(next(), next(), next(), other())

	shout := func(s string) string { return strings.ToUpper(s) + "!" }
	fmt.Println(apply([]string{"go", "ts"}, shout)) // functions are values
}
